// F10: copy a repo's history, plant one flipped comparison per chosen commit, add fix commits, write an answer key.
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, isAbsolute } from "node:path";
import { tmpdir } from "node:os";

export type Planted = { commit: string; file: string; line: number; fixCommit: string };
export type PlantOpts = { sourceRepo: string; outDir: string; keyPath: string; commits: string[]; seed: number };

const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|c|h|cc|cpp|cs|kt|swift|php)$/;
const OPERATOR = /===|!==|==|!=|<=|>=|(?<![=!<>-])<(?![=<\/])|(?<![=!<>-])>(?![=>])/g;
const FLIP: Record<string, string> = {
  "===": "!==", "!==": "===", "==": "!=", "!=": "==", "<": ">", ">": "<", "<=": ">=", ">=": "<=",
};

type Candidate = { file: string; line: number; col: number; op: string; text: string };

function git(cwd: string, args: string[], allowFail = false): string {
  const p = Bun.spawnSync(["git", ...args], { cwd, stdout: "pipe", stderr: "pipe" });
  if (p.exitCode !== 0 && !allowFail) {
    throw new Error(`git ${args.join(" ")} failed in ${cwd}: ${p.stderr.toString().trim()}`);
  }
  return p.stdout.toString();
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function isComment(text: string): boolean {
  return /^\s*(\/\/|#|\*|\/\*)/.test(text);
}

/** Lines added by a commit that contain a flippable comparison operator. */
function candidatesFor(repo: string, sha: string): Candidate[] {
  const diff = git(repo, ["show", "--format=", "-U0", "--no-color", "--no-renames", sha]);
  const out: Candidate[] = [];
  let file = "";
  let line = 0;
  for (const raw of diff.split("\n")) {
    if (raw.startsWith("+++ ")) {
      file = raw.startsWith("+++ b/") ? raw.slice(6) : "";
    } else if (raw.startsWith("@@")) {
      line = Number(/\+(\d+)/.exec(raw)![1]);
    } else if (raw.startsWith("+") && file) {
      const text = raw.slice(1);
      if (CODE_EXT.test(file) && !isComment(text) && !/^\s*import\b/.test(text)) {
        for (const m of text.matchAll(OPERATOR)) {
          if (!inString(text, m.index!)) out.push({ file, line, col: m.index!, op: m[0], text });
        }
      }
      line++;
    }
  }
  return out;
}

function inString(text: string, idx: number): boolean {
  let q = "";
  for (let i = 0; i < idx; i++) {
    const c = text[i];
    if (q) {
      if (c === "\\") i++;
      else if (c === q) q = "";
    } else if (c === '"' || c === "'" || c === "`") q = c;
  }
  return q !== "";
}

function flipAt(text: string, col: number, op: string): string {
  return text.slice(0, col) + FLIP[op] + text.slice(col + op.length);
}

function pickCandidate(cands: Candidate[], seed: number, index: number): Candidate {
  const rnd = mulberry32((seed ^ Math.imul(index + 1, 0x9e3779b1)) >>> 0);
  return cands[Math.floor(rnd() * cands.length)];
}

function editLine(repo: string, file: string, line: number, expected: string, replacement: string) {
  const path = join(repo, file);
  const lines = readFileSync(path, "utf8").split("\n");
  if (lines[line - 1] !== expected) {
    throw new Error(`${file}:${line} does not hold the expected text in the copy`);
  }
  lines[line - 1] = replacement;
  writeFileSync(path, lines.join("\n"));
}

function commitStaged(repo: string, file: string, args: string[]): string {
  git(repo, ["add", "--", file]);
  git(repo, ["commit", "--allow-empty", "--no-verify", "-q", ...args]);
  return git(repo, ["rev-parse", "HEAD"]).trim();
}

export async function plant(opts: PlantOpts): Promise<{ planted: Planted[] }> {
  const source = resolve(opts.sourceRepo);
  const outDir = resolve(opts.outDir);
  const keyPath = resolve(opts.keyPath);
  const rel = relative(outDir, keyPath);
  if (rel === "" || (!rel.startsWith("..") && !isAbsolute(rel))) {
    throw new Error("keyPath must be outside outDir");
  }

  const snapshot = () => ({
    head: git(source, ["rev-parse", "HEAD"]).trim(),
    status: git(source, ["status", "--porcelain"]),
  });
  const before = snapshot();

  const history = git(source, ["rev-list", "--reverse", "--no-merges", "HEAD"]).trim().split("\n").filter(Boolean);
  const wanted = new Set<string>();
  for (const c of opts.commits) {
    const full = git(source, ["rev-parse", "--verify", `${c}^{commit}`], true).trim();
    if (!full || !history.includes(full)) throw new Error(`commit ${c} is not a non-merge commit in the history of ${source}`);
    wanted.add(full);
  }

  const branch = git(source, ["symbolic-ref", "--short", "-q", "HEAD"], true).trim() || "planted";
  git(dirname(outDir), ["clone", "--no-local", "-q", source, outDir]);
  git(outDir, ["config", "user.name", "roster-planted"]);
  git(outDir, ["config", "user.email", "[REDACTED_EMAIL]"]);
  git(outDir, ["checkout", "--orphan", "planted-tmp", "-q"]);
  git(outDir, ["rm", "-rfq", "--ignore-unmatch", "."]);

  type Open = { entry: Planted & { sourceCommit: string; original: string; mutated: string }; tip: boolean };
  const planted: Open[] = [];
  const skipped: { commit: string; reason: string }[] = [];

  const fix = (p: Open["entry"], atLine: number) => {
    editLine(outDir, p.file, atLine, p.mutated, p.original);
    p.fixCommit = commitStaged(outDir, p.file, ["-m", `fix: restore comparison in ${p.file}`]);
  };

  let index = 0;
  for (const sha of history) {
    const pick = Bun.spawnSync(["git", "cherry-pick", "--no-commit", "--allow-empty", "--keep-redundant-commits", sha], { cwd: outDir, stderr: "pipe" });
    if (pick.exitCode !== 0) {
      git(outDir, ["cherry-pick", "--abort"], true);
      throw new Error(`replay of ${sha} conflicts with a planted change: ${pick.stderr.toString().trim()}`);
    }
    let note: Open["entry"] | undefined;
    if (wanted.has(sha)) {
      const cands = candidatesFor(source, sha);
      if (cands.length === 0) {
        skipped.push({ commit: sha, reason: "no editable line (no added line with a comparison operator)" });
      } else {
        const c = pickCandidate(cands, opts.seed, index++);
        const mutated = flipAt(c.text, c.col, c.op);
        editLine(outDir, c.file, c.line, c.text, mutated);
        note = { commit: "", file: c.file, line: c.line, fixCommit: "", sourceCommit: sha, original: c.text, mutated };
      }
    }
    git(outDir, ["add", "-A"]);
    git(outDir, ["commit", "--allow-empty", "--no-verify", "-q", "-C", sha]);
    if (note) {
      note.commit = git(outDir, ["rev-parse", "HEAD"]).trim();
      // Keep the bug live until the end when the line survives to the source tip; otherwise fix right away.
      const tipText = git(source, ["show", `HEAD:${note.file}`], true).split("\n");
      const tip = tipText.includes(note.original);
      const open = { entry: note, tip };
      planted.push(open);
      if (!tip) fix(note, note.line);
    }
  }

  for (const p of planted.filter((x) => x.tip)) {
    const lines = readFileSync(join(outDir, p.entry.file), "utf8").split("\n");
    let best = -1;
    lines.forEach((l, i) => {
      if (l === p.entry.mutated && (best < 0 || Math.abs(i + 1 - p.entry.line) < Math.abs(best + 1 - p.entry.line))) best = i;
    });
    if (best < 0) throw new Error(`planted line vanished from ${p.entry.file} before its fix`);
    fix(p.entry, best + 1);
  }

  git(outDir, ["branch", "-M", branch]);
  git(outDir, ["remote", "remove", "origin"], true);
  git(outDir, ["reflog", "expire", "--expire=now", "--all"]);
  git(outDir, ["gc", "--prune=now", "-q"], true);

  const after = snapshot();
  if (after.head !== before.head || after.status !== before.status) {
    throw new Error("source repo changed during planting");
  }

  const result = planted.map(({ entry: e }) => ({ commit: e.commit, file: e.file, line: e.line, fixCommit: e.fixCommit }));
  mkdirSync(dirname(keyPath), { recursive: true });
  writeFileSync(
    keyPath,
    JSON.stringify(
      {
        seed: opts.seed,
        sourceRepo: source,
        planted: planted.map(({ entry: e }) => ({
          commit: e.commit, sourceCommit: e.sourceCommit, file: e.file, line: e.line, fixCommit: e.fixCommit,
          original: e.original.trim(), mutated: e.mutated.trim(),
        })),
        skipped,
      },
      null,
      2,
    ) + "\n",
  );
  return { planted: result };
}
