// F10: copy a repo's history, plant one flipped comparison per chosen commit, add fix commits, write an answer key.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, isAbsolute } from "node:path";

export type Planted = { commit: string; file: string; line: number; fixCommit: string };
export type PlantOpts = { sourceRepo: string; outDir: string; keyPath: string; commits: string[]; seed: number };

const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|c|h|cc|cpp|cs|kt|swift|php)$/;
const OPERATOR = /===|!==|==|!=|<=|>=|(?<![=!<>-])<(?![=<\/])|(?<![=!<>-])>(?![=>])/g;
const FLIP: Record<string, string> = {
  "===": "!==", "!==": "===", "==": "!=", "!=": "==", "<": ">", ">": "<", "<=": ">=", ">=": "<=",
};

type Candidate = { file: string; line: number; col: number; op: string; text: string };
type Entry = Planted & { sourceCommit: string; original: string; mutated: string };

function git(cwd: string, args: string[], allowFail = false): string {
  const p = Bun.spawnSync(["git", ...args], { cwd, stdout: "pipe", stderr: "pipe" });
  if (p.exitCode !== 0 && !allowFail) {
    throw new Error(`git ${args.join(" ")} failed in ${cwd}: ${p.stderr.toString().trim()}`);
  }
  return p.stdout.toString();
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function inString(text: string, idx: number): boolean {
  let q = "";
  for (let i = 0; i < idx; i++) {
    const c = text[i];
    if (q) {
      if (c === "\\") i++;
      else if (c === q) q = "";
    } else if (c === '"' || c === "'" || c === "`") q = c;
  }
  return q !== "";
}

/** Added lines of a commit that contain a flippable comparison operator. */
function candidatesFor(repo: string, sha: string): Candidate[] {
  const diff = git(repo, ["show", "--format=", "-U0", "--no-color", "--no-renames", sha]);
  const out: Candidate[] = [];
  let file = "";
  let line = 0;
  for (const raw of diff.split("\n")) {
    if (raw.startsWith("+++ ")) {
      file = raw.startsWith("+++ b/") ? raw.slice(6) : "";
    } else if (raw.startsWith("@@")) {
      line = Number(/\+(\d+)/.exec(raw)![1]);
    } else if (raw.startsWith("+") && file) {
      const text = raw.slice(1);
      const skip = !CODE_EXT.test(file) || /^\s*(\/\/|#|\*|\/\*)/.test(text) || /^\s*import\b/.test(text);
      if (!skip) {
        for (const m of text.matchAll(OPERATOR)) {
          if (!inString(text, m.index!)) out.push({ file, line, col: m.index!, op: m[0], text });
        }
      }
      line++;
    }
  }
  return out;
}

function editLine(repo: string, file: string, line: number, expected: string, replacement: string) {
  const path = join(repo, file);
  const lines = readFileSync(path, "utf8").split("\n");
  if (lines[line - 1] !== expected) throw new Error(`${file}:${line} does not hold the expected text in the copy`);
  lines[line - 1] = replacement;
  writeFileSync(path, lines.join("\n"));
}

export async function plant(opts: PlantOpts): Promise<{ planted: Planted[] }> {
  const source = resolve(opts.sourceRepo);
  const outDir = resolve(opts.outDir);
  const keyPath = resolve(opts.keyPath);
  const rel = relative(outDir, keyPath);
  if (rel === "" || (!rel.startsWith("..") && !isAbsolute(rel))) throw new Error("keyPath must be outside outDir");

  const snapshot = () => ({
    head: git(source, ["rev-parse", "HEAD"]).trim(),
    status: git(source, ["status", "--porcelain"]),
  });
