  const history = git(source, ["rev-list", "--reverse", "--no-merges", "HEAD"]).trim().split("\n").filter(Boolean);
  const wanted = new Set<string>();
  for (const c of opts.commits) {
    const full = git(source, ["rev-parse", "--verify", `${c}^{commit}`], true).trim();
    if (!full || !history.includes(full)) throw new Error(`commit ${c} is not a non-merge commit in the history of ${source}`);
    wanted.add(full);
