import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { plant } from "../scripts/planted/plant";

const sh = (cwd: string, ...args: string[]) => {
  const p = Bun.spawnSync(["git", ...args], { cwd, stdout: "pipe", stderr: "pipe" });
  if (p.exitCode !== 0) throw new Error(p.stderr.toString());
  return p.stdout.toString().trim();
};

let root: string, src: string;
const shas: string[] = [];

beforeAll(() => {
  root = mkdtempSync(join(tmpdir(), "planted-"));
  src = join(root, "src-repo");
  mkdirSync(src);
  sh(src, "init", "-q", "-b", "main");
  sh(src, "config", "user.name", "t");
  sh(src, "config", "user.email", "[REDACTED_EMAIL]");
  const commit = (file: string, content: string, msg: string) => {
    writeFileSync(join(src, file), content);
    sh(src, "add", "-A");
    sh(src, "commit", "-q", "-m", msg);
    shas.push(sh(src, "rev-parse", "HEAD"));
  };
  commit("a.ts", "export const a = 1;\n", "c1 plain");
  commit("a.ts", "export const a = 1;\nexport function big(x: number) {\n  return x > 10;\n}\n", "c2 compare");
  commit("notes.md", "hello\n", "c3 docs only");
  commit("b.ts", "export function eq(a: number, b: number) {\n  if (a === b) return 0;\n  return a < b ? -1 : 1;\n}\n", "c4 more");
});

afterAll(() => rmSync(root, { recursive: true, force: true }));

describe("plant", () => {
  test("plants, fixes, writes key, leaves source untouched", async () => {
    const headBefore = sh(src, "rev-parse", "HEAD");
    const out = join(root, "out1");
    const keyPath = join(root, "key1.json");
    const r = await plant({ sourceRepo: src, outDir: out, keyPath, commits: [shas[3], shas[1], shas[2]], seed: 7 });

    expect(r.planted.length).toBe(2);
    expect(sh(src, "rev-parse", "HEAD")).toBe(headBefore);
    expect(sh(src, "status", "--porcelain")).toBe("");

    const key = JSON.parse(readFileSync(keyPath, "utf8"));
    expect(key.planted.length).toBe(2);
    expect(key.skipped.map((s: { commit: string }) => s.commit)).toEqual([shas[2]]);
    expect(existsSync(join(out, "key1.json"))).toBe(false);

    expect(r.planted[0].file).toBe("a.ts");
    expect(r.planted[1].file).toBe("b.ts");

    for (const p of r.planted) {
      const buggy = sh(out, "show", `${p.commit}:${p.file}`).split("\n")[p.line - 1];
      const fixed = sh(out, "show", `${p.fixCommit}:${p.file}`).split("\n")[p.line - 1];
      const orig = sh(src, "show", `HEAD:${p.file}`).split("\n")[p.line - 1];
      expect(buggy).not.toBe(orig);
      expect(fixed).toBe(orig);
      expect(sh(out, "log", "-1", "--format=%s", p.fixCommit)).toStartWith("fix:");
      sh(out, "merge-base", "--is-ancestor", p.commit, p.fixCommit);
    }
    expect(sh(out, "rev-parse", "HEAD^{tree}")).toBe(sh(src, "rev-parse", "HEAD^{tree}"));
    expect(sh(out, "status", "--porcelain")).toBe("");
  });

  test("deterministic for a seed", async () => {
    const a = await plant({ sourceRepo: src, outDir: join(root, "d1"), keyPath: join(root, "d1.json"), commits: [shas[3]], seed: 3 });
    const b = await plant({ sourceRepo: src, outDir: join(root, "d2"), keyPath: join(root, "d2.json"), commits: [shas[3]], seed: 3 });
    expect(a.planted[0].line).toBe(b.planted[0].line);
    expect(a.planted[0].file).toBe(b.planted[0].file);
  });

  test("rejects a key inside the copy", async () => {
    const out = join(root, "out3");
    await expect(plant({ sourceRepo: src, outDir: out, keyPath: join(out, "key.json"), commits: [shas[1]], seed: 1 })).rejects.toThrow(/outside/);
  });
});

